import math

class Solution:
    def valueAfterKSeconds(self, n: int, k: int) -> int:
        MOD = 10**9 + 7
        return math.comb(n + k - 1, k) % MOD

class Solution {
public:
    int valueAfterKSeconds(int n, int k) {
        long long MOD = 1e9 + 7;
        long long ans = 1;
        for (int i = 1; i <= k; ++i) {
            ans = ans * (n + k - i) % MOD;
            long long inv = 1, base = i, exp = MOD - 2;
            while (exp > 0) {
                if (exp % 2 == 1) inv = (inv * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            ans = (ans * inv) % MOD;
        }
        return ans;
    }
};

class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
    public int valueAfterKSeconds(int n, int k) {
        long MOD = 1_000_000_007L;
        long ans = 1;
        for (int i = 1; i <= k; ++i) {
            ans = ans * (n + k - i) % MOD;
            long inv = modPow(i, MOD - 2, MOD);
            ans = (ans * inv) % MOD;
        }
        return (int) ans;
    }
}

var valueAfterKSeconds = function(n, k) {
    const MOD = 1000000007n;
    function modPow(base, exp) {
        let res = 1n;
        base %= MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }
    let ans = 1n;
    for (let i = 1n; i <= BigInt(k); ++i) {
        ans = ans * (BigInt(n + k) - i) % MOD;
        const inv = modPow(i, MOD - 2n);
        ans = (ans * inv) % MOD;
    }
    return Number(ans);
};
